"""Identifiers: UUIDv7, generated by the application (spec 3.10 rule 8).

Globally unique, so ledgers exported from different installations can later be imported together
without collisions, and time-ordered, so sorting by id is sorting by creation. Ids made in the same
millisecond are kept strictly increasing, so order never depends on luck.
"""

from __future__ import annotations

import os
import threading
import time
import uuid

Id = uuid.UUID

_lock = threading.Lock()
_last = 0


def new_id() -> uuid.UUID:
    """A UUIDv7: 48 bits of unix milliseconds, version and variant bits, then randomness, bumped
    when needed so each id is greater than the last one issued by this process."""
    global _last
    millis = int(time.time() * 1000) & ((1 << 48) - 1)
    rand = int.from_bytes(os.urandom(10), "big")
    rand_a = (rand >> 62) & 0xFFF  # 12 bits
    rand_b = rand & ((1 << 62) - 1)  # 62 bits
    value = (millis << 80) | (0x7 << 76) | (rand_a << 64) | (0b10 << 62) | rand_b
    with _lock:
        if value <= _last:
            value = _last + 1
        _last = value
    return uuid.UUID(int=value)
